	GUI.Scanner.Button.MouseButton1Click:Connect(function()
		if not searching then
			searching=true
			debug('Scanning...', 3)
			GUI.Scanner.Button.Text='扫描后门'
			if not findRemote() then
				GUI.Scanner.Button.Text='扫不到后门'
				searching=false
			end
		end
	end)
